import json,hashlib
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
out=Path(__file__).parent;root=out.parent;manifest=json.loads((root/'evidence/version.json').read_text());assert manifest['version']=='core-journey-lowfi-v5';checks=[]
def hashes():return {f:hashlib.sha256((root/f).read_bytes()).hexdigest()==h for f,h in manifest['sha256'].items()}
def note(name,d):checks.append({'check':name,'observed':d});(out/'v5-independent-checks.json').write_text(json.dumps(checks,ensure_ascii=False,indent=2),encoding='utf-8');print(name,str(d)[:300],flush=True)
def frame(page,name,fit=True):
 page.evaluate('scrollTo(0,0)');page.wait_for_timeout(200);d=page.locator('.project-header,.scene,.wave,#dialogue,.performance,#next,#header-actions').evaluate_all('(es)=>({scroll:scrollY,w:innerWidth,h:innerHeight,items:es.map(e=>({id:e.id,cls:e.className,rect:e.getBoundingClientRect().toJSON(),text:e.id=="dialogue"?e.innerText:""}))})');note(name,d);page.screenshot(path=str(out/(name+'.png')))
 if fit:assert all(e['rect']['top']>=0 and e['rect']['bottom']<=d['h'] for e in d['items']),(name,d)
 return d

def capture(page,name):page.locator('#record').click();expect(page.locator('#capture-badge')).to_be_visible();assert page.locator('#scrub').is_disabled() and page.locator('#pause').is_hidden();frame(page,name+'-recording');page.wait_for_function('!document.querySelector("#take").disabled',timeout=10000);frame(page,name+'-candidate')
def st(page):return page.evaluate('JSON.parse(localStorage.getItem("dubbed-lowfi-v1"))')
assert all(hashes().values())
with sync_playwright() as p:
 b=p.chromium.launch(channel='chrome',headless=True);page=b.new_page(viewport={'width':1882,'height':902},device_scale_factor=1);errs=[];page.on('pageerror',lambda e:errs.append(str(e)));page.goto('http://127.0.0.1:5178');page.wait_for_function('document.querySelector("#scene").readyState>=3');page.evaluate('document.fonts.ready');note('environment',{'browser':b.version,'date':'2026-10-27','os':'Windows','DPR':1,'zoom':'100%','version':manifest['version']});frame(page,'v5-review-normal');page.locator('#replay').click();page.wait_for_timeout(450);page.locator('#pause').click();paused=page.locator('#scene').evaluate('(e)=>e.currentTime');page.locator('#pause').click();page.wait_for_timeout(160);assert page.locator('#scene').evaluate('(e)=>e.currentTime')>paused;note('Original Pause/Resume retains position',True);capture(page,'v5-review-normal');page.locator('#take').click();page.wait_for_function('!document.querySelector("#take-audio").paused && document.querySelector("#take-audio").currentTime>.2');page.locator('#pause').click();page.locator('#next').click();expect(page.locator('#position')).to_have_text('Line 2 of 3');frame(page,'v5-review-normal-saved');capture(page,'v5-review-normal-line2');page.locator('#next').click();expect(page.locator('#position')).to_have_text('Line 3 of 3');capture(page,'v5-review-normal-line3');page.locator('#next').click();expect(page.locator('#result')).to_be_visible(timeout=5000);page.wait_for_function('document.querySelector("#result").readyState>=3');page.locator('#result').evaluate('(e)=>e.play()');page.wait_for_timeout(250);page.locator('#result').evaluate('(e)=>e.pause()');page.screenshot(path=str(out/'v5-review-result.png'));page.locator('#return').click();expect(page.locator('#position')).to_have_text('Line 1 of 3');assert page.locator('#to-result').is_visible();frame(page,'v5-review-normal-completed')
 page.set_viewport_size({'width':1280,'height':600});page.locator('.lab summary').click();page.locator('#long-line').check();page.locator('.lab summary').click();frame(page,'v5-review-short-long-completed');accepted=st(page)['accepted'][0]['id'];capture(page,'v5-review-short-long');candidate=st(page)['candidates'][0]['id'];page.locator('.lab summary').click();page.locator('#fail-save').check();page.locator('.lab summary').click();page.locator('#next').click();expect(page.locator('#feedback')).to_contain_text('Couldn’t save');assert st(page)['accepted'][0]['id']==accepted and st(page)['candidates'][0]['id']==candidate;frame(page,'v5-review-short-long-failed-save',fit=False);note('Short failed replacement keeps old accepted and exact candidate',True);page.locator('#take').click();page.wait_for_function('!document.querySelector("#take-audio").paused && document.querySelector("#take-audio").currentTime>.2');page.locator('#pause').click();page.get_by_role('button',name='Retry save',exact=True).click();expect(page.locator('#position')).to_have_text('Line 2 of 3');assert st(page)['accepted'][0]['id']==candidate;frame(page,'v5-review-short-long-after-retry');note('Short failed candidate remains audible and Retry accepts exact identity',True)
 note('page errors',errs);assert not errs;note('final stable hashes',hashes());assert all(hashes().values());b.close()
